+/**
+ * Redacts sensitive information from strings before logging
+ * Prevents leakage of Telegram bot tokens in logs, crash reports, and error messages
+ * @param {string} str - Input string that may contain sensitive data
+ * @returns {string} - String with sensitive data redacted
+ */
+function redactSensitiveInfo(str) {
+  if (typeof str !== 'string') return str;
+  
+  // Redact Telegram bot tokens (format: bot<digits>:<alphanumeric>)
+  // Tokens appear in URLs like: https://api.telegram.org/bot123456:ABC.../method
+  // Also handles tokens that may appear in error messages/stack traces
+  const tokenPattern = /bot\d{8,}:[A-Za-z0-9_-]{30,}/gi;
+  return str.replace(tokenPattern, 'bot[TOKEN_REDACTED]');
+}
+
+module.exports = {
+  redactSensitiveInfo
+};
