+/**
+ * Validates that the target URL domain is allowed for the given credentials.
+ * Prevents credential exfiltration through improper wildcard domain matching.
+ */
+function validateDomainForCredentials(
+	node: INodeTypeDescription,
+	credentials: IHttpRequestCredentials,
+	url: string,
+): void {
+	if (!credentials.allowedDomains || credentials.allowedDomains.length === 0) {
+		return;
+	}
+
+	const targetDomain = new URL(url).hostname;
+
+	for (const allowedDomain of credentials.allowedDomains) {
+		if (isDomainMatch(targetDomain, allowedDomain)) {
+			return; // Domain is allowed
+		}
+	}
+
+	throw new NodeOperationError(
+		node,
+		`The domain "${targetDomain}" is not in the allowed domains list for these credentials`,
+	);
+}
+
+function isDomainMatch(targetDomain: string, allowedDomain: string): boolean {
+	if (allowedDomain.startsWith('*.')) {
+		// Wildcard pattern: *.example.com should only match subdomain.example.com
+		// Escape special regex characters and anchor the pattern
+		const baseDomain = allowedDomain.slice(2).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+		const pattern = new RegExp(`^[^.]+\\.${baseDomain}$`, 'i');
+		return pattern.test(targetDomain);
+	}
+	// Exact match (case-insensitive)
+	return targetDomain.toLowerCase() === allowedDomain.toLowerCase();
+}

