+const dns = require('dns');
+const {promisify} = require('util');
+const net = require('net');
+
+const resolve = promisify(dns.resolve4);
+
+const PRIVATE_IP_RANGES = [
+    {start: '0.0.0.0', end: '0.255.255.255'},       // Current network
+    {start: '10.0.0.0', end: '10.255.255.255'},     // Private Class A
+    {start: '127.0.0.0', end: '127.255.255.255'},   // Loopback
+    {start: '169.254.0.0', end: '169.254.255.255'}, // Link-local (AWS metadata)
+    {start: '172.16.0.0', end: '172.31.255.255'},   // Private Class B
+    {start: '192.168.0.0', end: '192.168.255.255'}, // Private Class C
+    {start: '224.0.0.0', end: '239.255.255.255'}    // Multicast
+];
+
+function ipToNumber(ip) {
+    const parts = ip.split('.').map(Number);
+    return (parts[0] << 24) + (parts[1] << 16) + (parts[2] << 8) + parts[3];
+}
+
+function isPrivateIp(ip) {
+    if (!net.isIPv4(ip)) {
+        return true; // Block non-IPv4 addresses for safety
+    }
+    
+    const ipNum = ipToNumber(ip);
+    
+    for (const range of PRIVATE_IP_RANGES) {
+        const startNum = ipToNumber(range.start);
+        const endNum = ipToNumber(range.end);
+        if (ipNum >= startNum && ipNum <= endNum) {
+            return true;
+        }
+    }
+    
+    return false;
+}
+
+async function isSafeUrl(urlString) {
+    try {
+        const url = new URL(urlString);
+        const hostname = url.hostname;
+        
+        // Check if hostname is already an IP
+        if (net.isIPv4(hostname)) {
+            return !isPrivateIp(hostname);
+        }
+        
+        // Resolve DNS and check resolved IPs
+        const addresses = await resolve(hostname);
+        for (const addr of addresses) {
+            if (isPrivateIp(addr)) {
+                return false;
+            }
+        }
+        
+        return true;
+    } catch {
+        return false;
+    }
+}
+
+module.exports = {isSafeUrl, isPrivateIp};

