+import { URL } from 'url';
+
+/**
+ * Validates that a URL is safe to use for external requests.
+ * Prevents SSRF attacks by blocking private IP ranges and internal hosts.
+ */
+export function isSafeUrl(urlString: string): boolean {
+  let url: URL;
+  
+  try {
+    url = new URL(urlString);
+  } catch {
+    return false;
+  }
+
+  // Only allow http and https protocols
+  if (!['http:', 'https:'].includes(url.protocol)) {
+    return false;
+  }
+
+  const hostname = url.hostname.toLowerCase();
+
+  // Block localhost and known internal hostnames
+  const blockedHosts = [
+    'localhost',
+    'metadata.google.internal',
+    '169.254.169.254',  // AWS metadata IP
+  ];
+  
+  if (blockedHosts.includes(hostname)) {
+    return false;
+  }
+
+  // Block private IP ranges (RFC 1918 and link-local)
+  const privateIpPatterns = [
+    /^10\./,                                    // 10.0.0.0/8
+    /^172\.(1[6-9]|2[0-9]|3[0-1])\./,          // 172.16.0.0/12
+    /^192\.168\./,                              // 192.168.0.0/16
+    /^127\./,                                   // 127.0.0.0/8 (loopback)
+    /^169\.254\./,                              // 169.254.0.0/16 (link-local)
+  ];
+
+  if (privateIpPatterns.some(pattern => pattern.test(hostname))) {
+    return false;
+  }
+
+  return true;
+}
