+import { lookup } from 'dns'
+import { promisify } from 'util'
+
+const PRIVATE_IP_RANGES = [
+  /^127\./,                           // Loopback
+  /^10\./,                            // Private Class A
+  /^172\.(1[6-9]|2[0-9]|3[0-1])\./,   // Private Class B
+  /^192\.168\./,                      // Private Class C
+  /^169\.254\./,                      // Link-local
+  /^0\.0\.0\.0$/,                     // All interfaces
+  /^::1$/,                            // IPv6 loopback
+  /^fc/i,                             // IPv6 private
+  /^fe80:/i,                          // IPv6 link-local
+]
+
+export function isInternalIp(ip: string): boolean {
+  return PRIVATE_IP_RANGES.some(range => range.test(ip))
+}
+
+export async function validateDestinationUrl(urlString: string): Promise<void> {
+  let parsedUrl: URL
+  
+  try {
+    parsedUrl = new URL(urlString, 'http://localhost')
+  } catch {
+    throw new Error(`Invalid URL: ${urlString}`)
+  }
+  
+  // Block non-http(s) protocols
+  if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
+    throw new Error(`Blocked protocol in redirect: ${parsedUrl.protocol}`)
+  }
+  
+  const hostname = parsedUrl.hostname
+  
+  // Check if hostname matches private IP patterns
+  if (isInternalIp(hostname)) {
+    throw new Error(`Blocked redirect to internal IP: ${hostname}`)
+  }
+  
+  // Resolve hostname to check for DNS rebinding attacks
+  const dnsLookup = promisify(lookup)
+  const resolved = await dnsLookup(hostname).catch(() => null)
+  if (resolved && isInternalIp(resolved.address)) {
+    throw new Error(`Blocked redirect to hostname resolving to internal IP: ${hostname}`)
+  }
+}

