@@ -0,0 +1,28 @@
+/**
+ * Validates and sanitizes a redirect URL to prevent open redirect attacks.
+ * Only allows relative URLs that start with '/' but not '//' (protocol-relative).
+ * 
+ * @param redirect - The redirect URL to validate
+ * @param defaultRedirect - The default URL to return if validation fails (default: '/')
+ * @returns A safe redirect URL
+ */
+export function sanitizeRedirect(redirect: string | null | undefined, defaultRedirect: string = '/'): string {
+  if (!redirect || typeof redirect !== 'string') {
+    return defaultRedirect;
+  }
+
+  // Trim whitespace
+  const trimmedRedirect = redirect.trim();
+
+  // Only allow relative URLs starting with /
+  // This prevents:
+  // - Absolute URLs (http://evil.com, https://evil.com)
+  // - Protocol-relative URLs (//evil.com)
+  // - JavaScript URLs (javascript:...)
+  // - Data URLs (data:...)
+  if (trimmedRedirect.startsWith('/') && !trimmedRedirect.startsWith('//')) {
+    return trimmedRedirect;
+  }
+
+  return defaultRedirect;
+}
