+/**
+ * URL validation utility to prevent API key leakage
+ * Only whitelisted domains are allowed to receive backend API keys
+ */
+
+const ALLOWED_DOMAINS = new Set([
+  'api.openai.com',
+  'api.anthropic.com',
+  'openai.azure.com',
+  'api.deepseek.com',
+  'api.moonshot.cn',
+  'api.minimax.chat',
+  'api.together.xyz',
+  'openrouter.ai',
+]);
+
+export const isAllowedBaseUrl = (url: string | undefined): boolean => {
+  if (!url) return false;
+
+  try {
+    const { hostname } = new URL(url);
+    // Check if hostname matches an allowed domain or is a subdomain of one
+    for (const domain of ALLOWED_DOMAINS) {
+      if (hostname === domain || hostname.endsWith(`.${domain}`)) {
+        return true;
+      }
+    }
+    return false;
+  } catch {
+    return false;
+  }
+};

