+// Input validation helpers for security-critical user inputs
+
+const VALID_NAME_REGEX = /^[a-zA-Z_][a-zA-Z0-9_]{0,63}$/;
+const MAX_NAME_LENGTH = 64;
+
+export function validateTableName(name: string): void {
+  if (!name || typeof name !== 'string') {
+    throw new Error('Table name is required and must be a string');
+  }
+  
+  if (name.length > MAX_NAME_LENGTH) {
+    throw new Error(`Table name cannot exceed ${MAX_NAME_LENGTH} characters`);
+  }
+  
+  if (!VALID_NAME_REGEX.test(name)) {
+    throw new Error('Invalid table name. Name must start with a letter or underscore and contain only alphanumeric characters and underscores');
+  }
+}
+
+export function validateColumnName(name: string): void {
+  if (!name || typeof name !== 'string') {
+    throw new Error('Column name is required and must be a string');
+  }
+  
+  if (name.length > MAX_NAME_LENGTH || !VALID_NAME_REGEX.test(name)) {
+    throw new Error('Invalid column name. Name must start with a letter or underscore and contain only alphanumeric characters and underscores');
+  }
+}
