+/**
+ * Sanitizes a URL to prevent XSS attacks via javascript: and other dangerous protocols.
+ * Returns empty string for dangerous URLs, otherwise returns the original URL.
+ */
+export const sanitizeUrl = (url: string | null | undefined): string => {
+  if (!url) {
+    return "";
+  }
+
+  const trimmedUrl = url.trim().toLowerCase();
+
+  // Block dangerous protocols that could execute JavaScript
+  const dangerousProtocols = [
+    "javascript:",
+    "vbscript:",
+    "data:text/html",
+  ];
+
+  if (dangerousProtocols.some((protocol) => trimmedUrl.startsWith(protocol))) {
+    return "";
+  }
+
+  return url;
+};
