+import path from 'path';
+
+/**
+ * Validates that a resolved path remains within the expected base directory.
+ * Prevents directory traversal attacks by ensuring the target path
+ * cannot escape the intended directory.
+ *
+ * @param targetPath - The path to validate (should be resolved)
+ * @param baseDir - The base directory that the path must remain within
+ * @returns true if the path is within the base directory, false otherwise
+ */
+export function isPathWithin(targetPath: string, baseDir: string): boolean {
+	const resolvedBase = path.resolve(baseDir);
+	const resolvedTarget = path.resolve(targetPath);
+
+	return resolvedTarget.startsWith(resolvedBase + path.sep) ||
+	       resolvedTarget === resolvedBase;
+}

