+import type { ServerRequestEvent } from '../../shared/types';
+
+const CSRF_HEADER = 'x-csrf-token';
+const CSRF_COOKIE = 'qcsrftoken';
+const CSRF_SECRET_LENGTH = 32;
+
+/**
+ * Generates a cryptographically secure CSRF token
+ */
+export function generateCsrfToken(): string {
+  const array = new Uint8Array(CSRF_SECRET_LENGTH);
+  crypto.getRandomValues(array);
+  return Array.from(array, (b) => b.toString(16).padStart(2, '0')).join('');
+}
+
+/**
+ * Validates CSRF token for incoming requests
+ * Checks that the token in the header matches the token in the cookie
+ */
+export function validateCsrfToken(requestEv: ServerRequestEvent): boolean {
+  const request = requestEv.request;
+  
+  // Get token from cookie
+  const cookieHeader = request.headers.get('cookie') || '';
+  const cookies = parseCookies(cookieHeader);
+  const cookieToken = cookies[CSRF_COOKIE];
+  
+  // Get token from header or body
+  const headerToken = request.headers.get(CSRF_HEADER);
+  
+  // Both tokens must be present and match
+  if (!cookieToken || !headerToken) {
+    // Fallback: Check Origin header for same-origin requests
+    const origin = request.headers.get('origin');
+    const host = request.headers.get('host');
+    if (origin && host) {
+      try {
+        const originUrl = new URL(origin);
+        return originUrl.host === host;
+      } catch {
+        return false;
+      }
+    }
+    return false;
+  }
+  
+  return cookieToken === headerToken;
+}
+
+/**
+ * Parse cookie string into key-value object
+ */
+function parseCookies(cookieString: string): Record<string, string> {
+  const cookies: Record<string, string> = {};
+  for (const cookie of cookieString.split(';')) {
+    const [name, ...rest] = cookie.trim().split('=');
+    if (name && rest.length > 0) {
+      cookies[name] = rest.join('=');
+    }
+  }
+  return cookies;
+}
