+/**
+ * CSRF protection middleware for loopback-bound browser control service.
+ * Rejects cross-origin mutating requests from non-loopback origins.
+ */
+
+const LOOPBACK_HOSTNAMES = new Set([
+  'localhost',
+  '127.0.0.1',
+  '::1',
+  '[::1]'
+]);
+
+function isLoopbackOrigin(hostname) {
+  if (!hostname) return false;
+  const normalized = hostname.toLowerCase();
+  return LOOPBACK_HOSTNAMES.has(normalized) || normalized.startsWith('127.');
+}
+
+function extractHostnameFromUrl(urlString) {
+  try {
+    return new URL(urlString).hostname;
+  } catch {
+    return null;
+  }
+}
+
+function csrfProtection(req, res, next) {
+  const mutatingMethods = ['POST', 'PUT', 'PATCH', 'DELETE'];
+  
+  if (!mutatingMethods.includes(req.method.toUpperCase())) {
+    return next();
+  }
+
+  // Check Sec-Fetch-Site header (modern browsers)
+  const secFetchSite = req.headers['sec-fetch-site'];
+  if (secFetchSite === 'cross-site') {
+    return res.status(403).json({ error: 'Cross-site requests forbidden' });
+  }
+
+  // Validate Origin or Referer is from loopback
+  const originHost = extractHostnameFromUrl(req.headers['origin'] || '');
+  const refererHost = extractHostnameFromUrl(req.headers['referer'] || '');
+  
+  if (originHost && !isLoopbackOrigin(originHost)) {
+    return res.status(403).json({ error: 'Origin must be loopback address' });
+  }
+  if (!originHost && refererHost && !isLoopbackOrigin(refererHost)) {
+    return res.status(403).json({ error: 'Referer must be loopback address' });
+  }
+
+  next();
+}
+
+module.exports = { csrfProtection, isLoopbackOrigin };
