+import { randomBytes } from "node:crypto"

 // Generate a random authentication token for this server instance
 const AUTH_TOKEN = randomBytes(32).toString("hex")

 // Authentication middleware
 function authMiddleware(req: any, res: any, next: any) {
   const providedToken = req.headers["authorization"]?.replace("Bearer ", "")
   if (!providedToken || providedToken !== AUTH_TOKEN) {
     res.status(401).json({ error: "Unauthorized" })
     return
   }
   next()
 }

 // CORS configuration - restrict to same origin only
 const corsOptions = {
   origin: (origin: string | undefined, callback: (err: Error | null, allow?: boolean) => void) => {
     // Allow requests with no origin (like mobile apps, curl, or same-origin requests)
     if (!origin) {
       callback(null, true)
       return
     }
     // Reject cross-origin requests from browsers
     callback(new Error("Not allowed by CORS"), false)
   },
   credentials: true,
 }

 // Apply middleware before routes
 app.use(cors(corsOptions))

 // Protect sensitive endpoints with authentication
 app.use("/session/:id/shell", authMiddleware)
 app.use("/pty", authMiddleware)
 app.use("/file/content", authMiddleware)

 // Export the token so it can be communicated to authorized clients
 export function getAuthToken() {
   return AUTH_TOKEN
 }

