+import { Request, Response, NextFunction } from 'express';
+
+/**
+ * Allowed hosts for DNS rebinding protection when running on localhost.
+ * These are the only values permitted in the Host header to prevent
+ * DNS rebinding attacks against local MCP servers.
+ */
+const ALLOWED_LOCALHOST_HOSTS = [
+    'localhost',
+    '127.0.0.1',
+    '[::1]',
+];
+
+/**
+ * Middleware that validates the Host header to prevent DNS rebinding attacks.
+ * When running an MCP server on localhost without authentication, this middleware
+ * ensures that requests only come from allowed localhost origins.
+ * 
+ * @returns Express middleware function
+ */
+export function hostHeaderValidation() {
+    return (req: Request, res: Response, next: NextFunction): void => {
+        const host = req.headers.host;
+        
+        if (!host) {
+            res.status(400).send('Bad Request: Missing Host header');
+            return;
+        }
+        
+        // Extract hostname without port
+        const hostname = host.split(':')[0].toLowerCase();
+        
+        const isAllowed = ALLOWED_LOCALHOST_HOSTS.includes(hostname);
+        
+        if (!isAllowed) {
+            res.status(403).send('Forbidden: Invalid Host header');
+            return;
+        }
+        
+        next();
+    };
+}
