+'use strict';
+
+const { isPrivateAttribute } = require('./is-private-attribute');
+
+/**
+ * Recursively sanitizes a lookup object to remove queries on private fields
+ * @param {object} lookup - The lookup query object
+ * @param {object} schema - The content type schema
+ * @param {object} strapi - Strapi instance
+ * @returns {object} - Sanitized lookup object
+ */
+const sanitizeLookup = (lookup, schema, strapi) => {
+  if (!lookup || typeof lookup !== 'object') {
+    return lookup;
+  }
+
+  const sanitizedLookup = {};
+
+  for (const [key, value] of Object.entries(lookup)) {
+    // Check if this is a relation attribute
+    const attribute = schema?.attributes?.[key];
+
+    if (attribute?.type === 'relation') {
+      // Get the target content type for the relation
+      const targetUid = attribute.target;
+      const targetSchema = strapi.contentType(targetUid);
+
+      // Recursively sanitize the nested lookup for the relation
+      sanitizedLookup[key] = sanitizeLookup(value, targetSchema, strapi);
+    } else if (attribute?.type === 'component') {
+      // Handle component attributes
+      const componentUid = attribute.component;
+      const componentSchema = strapi.components[componentUid];
+      sanitizedLookup[key] = sanitizeLookup(value, componentSchema, strapi);
+    } else {
+      // Check if the field is private
+      if (isPrivateAttribute(schema, key)) {
+        continue; // Skip private fields
+      }
+      sanitizedLookup[key] = value;
+    }
+  }
+
+  return sanitizedLookup;
+};
+
+module.exports = {
+  sanitizeLookup,
+};
