+const ALLOWED_BROWSER_PATHS: string[] = [];
+const BLOCKED_ARGS = [
+    '--browser',
+    '--app',
+    '--utility-cmd-prefix',
+    '--renderer-cmd-prefix',
+    '--gpu-launcher',
+    '--service-pipe-token',
+    '--crashpad-handler-pid',
+    '--extension-process',
+    '--nacl-broker',
+    '--nacl-loader',
+    '--confine-unto-packages',
+    '--load-and-launch-app',
+    '--load-app',
+    '--uninstall-app',
+    '--app-id',
+    '--enable-logging',
+    '--log-file'
+];
+
+export const validateBrowserLaunchOptions = (options: any = {}): void => {
+    if (options.executablePath) {
+        if (ALLOWED_BROWSER_PATHS.length > 0 && !ALLOWED_BROWSER_PATHS.includes(options.executablePath)) {
+            throw new Error(`executablePath is restricted. Allowed paths: ${ALLOWED_BROWSER_PATHS.join(', ')}`);
+        }
+        if (ALLOWED_BROWSER_PATHS.length === 0) {
+            throw new Error('executablePath is not allowed for security reasons. Use the default browser installation.');
+        }
+    }
+    
+    if (options.args && Array.isArray(options.args)) {
+        for (const arg of options.args) {
+            const argName = typeof arg === 'string' ? arg.split('=')[0] : '';
+            if (BLOCKED_ARGS.some(blocked => argName.startsWith(blocked))) {
+                throw new Error(`Browser argument '${argName}' is not allowed for security reasons`);
+            }
+        }
+    }
+    
+    if (options.ignoreDefaultArgs) {
+        throw new Error('ignoreDefaultArgs is not allowed for security reasons');
+    }
+    
+    if (options.pipe !== undefined && options.pipe !== false) {
+        throw new Error('pipe option is not allowed for security reasons');
+    }
+    
+    if (options.extraPrefsFirefox) {
+        throw new Error('extraPrefsFirefox is not allowed for security reasons');
+    }
+};

