+import dns from 'dns'
+import { promisify } from 'util'
+
+const dnsLookup = promisify(dns.lookup)
+
+// Private IP ranges that should be blocked for SSRF protection
+const PRIVATE_IP_PATTERNS = [
+    /^10\./, // 10.0.0.0/8
+    /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // 172.16.0.0/12
+    /^192\.168\./, // 192.168.0.0/16
+    /^127\./, // 127.0.0.0/8 (localhost)
+    /^169\.254\./, // 169.254.0.0/16 (link-local, includes cloud metadata 169.254.169.254)
+    /^0\.0\.0\.0/, // 0.0.0.0/8
+    /^::1$/, // IPv6 localhost
+    /^fc00:/i, // IPv6 ULA
+    /^fe80:/i, // IPv6 link-local
+    /^::ffff:10\./i, // IPv4-mapped IPv6 private
+    /^::ffff:172\.(1[6-9]|2[0-9]|3[0-1])\./i,
+    /^::ffff:192\.168\./i,
+    /^::ffff:127\./i
+]
+
+/**
+ * Validates a URL and checks if it points to a private/internal IP address.
+ * This prevents SSRF attacks by blocking requests to internal network resources.
+ * @param urlString - The URL to validate
+ * @returns true if the URL is safe, false if it's an SSRF attempt
+ */
+export async function validateUrlForSSRF(urlString: string): Promise<{ valid: boolean; error?: string }> {
+    try {
+        const url = new URL(urlString)
+
+        // Only allow http and https protocols
+        if (!['http:', 'https:'].includes(url.protocol)) {
+            return { valid: false, error: 'Only HTTP and HTTPS protocols are allowed' }
+        }
+
+        // Block common internal hostnames
+        const blockedHosts = ['localhost', 'localhost.localdomain', 'ip6-localhost', 'ip6-loopback']
+        if (blockedHosts.includes(url.hostname.toLowerCase())) {
+            return { valid: false, error: 'Access to internal hostnames is not allowed' }
+        }
+
+        // Resolve the hostname to check actual IP address (prevents DNS rebinding)
+        const { address } = await dnsLookup(url.hostname)
+
+        // Check if resolved IP is in private range
+        for (const pattern of PRIVATE_IP_PATTERNS) {
+            if (pattern.test(address)) {
+                return { valid: false, error: 'Access to private IP addresses is not allowed' }
+            }
+        }
+
+        return { valid: true }
+    } catch (error) {
+        return { valid: false, error: 'Invalid URL format' }
+    }
+}
