+import type { ImageConfigComplete } from "next/dist/shared/lib/image-config";
+
+/**
+ * Validates if a remote URL is allowed based on the image configuration.
+ * This prevents SSRF attacks by ensuring only whitelisted domains can be
+ * loaded through the /_next/image endpoint.
+ */
+export function isRemoteUrlAllowed(
+  url: string,
+  imageConfig: ImageConfigComplete
+): boolean {
+  let parsedUrl: URL;
+
+  try {
+    parsedUrl = new URL(url);
+  } catch {
+    return false;
+  }
+
+  // Block internal/private IP addresses to prevent SSRF to internal services
+  if (isInternalIpAddress(parsedUrl.hostname)) {
+    return false;
+  }
+
+  // Check against remotePatterns (preferred method in Next.js 14+)
+  if (imageConfig.remotePatterns && imageConfig.remotePatterns.length > 0) {
+    return imageConfig.remotePatterns.some((pattern) => {
+      return matchesRemotePattern(parsedUrl, pattern);
+    });
+  }
+
+  // Fallback to legacy domains configuration
+  if (imageConfig.domains && imageConfig.domains.length > 0) {
+    return imageConfig.domains.includes(parsedUrl.hostname);
+  }
+
+  // If no remotePatterns or domains are configured, deny all remote URLs
+  return false;
+}
+
+function matchesRemotePattern(
+  url: URL,
+  pattern: NonNullable<ImageConfigComplete["remotePatterns"]>[number]
+): boolean {
+  if (pattern.protocol && url.protocol.replace(":", "") !== pattern.protocol) {
+    return false;
+  }
+
+  if (pattern.hostname) {
+    const regex = new RegExp(
+      `^${escapeRegExp(pattern.hostname).replace(/\\\*/g, ".*")}$`
+    );
+    if (!regex.test(url.hostname)) {
+      return false;
+    }
+  }
+
+  if (pattern.port && url.port !== pattern.port) {
+    return false;
+  }
+
+  if (pattern.pathname) {
+    const regex = new RegExp(
+      `^${escapeRegExp(pattern.pathname).replace(/\\\*/g, ".*")}$`
+    );
+    if (!regex.test(url.pathname)) {
+      return false;
+    }
+  }
+
+  return true;
+}
+
+function escapeRegExp(str: string): string {
+  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
+}
+
+/**
+ * Checks if a hostname points to an internal/private IP address.
+ * This prevents SSRF attacks targeting internal services.
+ */
+function isInternalIpAddress(hostname: string): boolean {
+  const lowerHostname = hostname.toLowerCase();
+
+  // Block localhost variants
+  if (lowerHostname === "localhost" || lowerHostname === "127.0.0.1" || lowerHostname === "::1") {
+    return true;
+  }
+
+  // Block internal IP ranges (10.x.x.x, 172.16-31.x.x, 192.168.x.x)
+  const internalIpPatterns = [
+    /^10\.\d{1,3}\.\d{1,3}\.\d{1,3}$/,
+    /^172\.(1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3}$/,
+    /^192\.168\.\d{1,3}\.\d{1,3}$/,
+    /^169\.254\.\d{1,3}\.\d{1,3}$/, // Link-local
+    /^0\.0\.0\.0$/,
+  ];
+
+  return internalIpPatterns.some((pattern) => pattern.test(hostname));
+}

