+import { lookup } from 'dns';
+import { parse } from 'url';
+
+const PRIVATE_IP_RANGES = [
+  /^127\./, // Loopback
+  /^10\./, // Class A private
+  /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // Class B private
+  /^192\.168\./, // Class C private
+  /^169\.254\./, // Link-local
+  /^0\.0\.0\.0/, // All interfaces
+  /^::1$/, // IPv6 loopback
+  /^::$/, // IPv6 all addresses
+  /^fc/i, // IPv6 unique local
+  /^fd/i, // IPv6 unique local
+  /^fe80:/i, // IPv6 link-local
+];
+
+const BLOCKED_HOSTNAMES = [
+  'localhost',
+  'localhost.localdomain',
+  'ip6-localhost',
+  'ip6-loopback',
+];
+
+function isPrivateIP(ip: string): boolean {
+  // Check IPv4 private ranges
+  for (const range of PRIVATE_IP_RANGES) {
+    if (range.test(ip)) {
+      return true;
+    }
+  }
+  
+  // Check for IPv6 loopback variations
+  if (ip === '::1' || ip === '::' || ip.startsWith('fc') || ip.startsWith('fd') || ip.toLowerCase().startsWith('fe80:')) {
+    return true;
+  }
+  
+  return false;
+}
+
+function isValidPublicIP(ip: string): boolean {
+  // Basic IPv4 validation
+  const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;
+  if (ipv4Regex.test(ip)) {
+    const parts = ip.split('.').map(Number);
+    // Check each octet is valid
+    if (parts.some(part => part < 0 || part > 255)) {
+      return false;
+    }
+    return !isPrivateIP(ip);
+  }
+  
+  // IPv6 addresses - check if private
+  return !isPrivateIP(ip);
+}
+
+export async function validateEndpointUrl(endpointUrl: string): Promise<string> {
+  if (!endpointUrl) {
+    throw new Error('Endpoint URL is required');
+  }
+
+  let parsedUrl;
+  try {
+    parsedUrl = new URL(endpointUrl);
+  } catch {
+    throw new Error('Invalid endpoint URL format');
+  }
+
+  // Only allow http and https protocols
+  if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
+    throw new Error('Only HTTP and HTTPS protocols are allowed');
+  }
+
+  const hostname = parsedUrl.hostname.toLowerCase();
+
+  // Block known internal hostnames
+  if (BLOCKED_HOSTNAMES.includes(hostname)) {
+    throw new Error('Access to internal hostnames is not allowed');
+  }
+
+  // Block hostnames that look like IP addresses (private ranges)
+  if (isPrivateIP(hostname)) {
+    throw new Error('Access to private IP addresses is not allowed');
+  }
+
+  // DNS rebinding protection: resolve the hostname and check the IP
+  return new Promise((resolve, reject) => {
+    lookup(hostname, { family: 0 }, (err, address) => {
+      if (err) {
+        reject(new Error('Failed to resolve endpoint hostname'));
+        return;
+      }
+
+      if (isPrivateIP(address)) {
+        reject(new Error('Endpoint resolves to a private IP address'));
+        return;
+      }
+
+      resolve(endpointUrl);
+    });
+  });
+}
+
+export function validateEndpointUrlSync(endpointUrl: string): string {
+  if (!endpointUrl) {
+    throw new Error('Endpoint URL is required');
+  }
+
+  let parsedUrl;
+  try {
+    parsedUrl = new URL(endpointUrl);
+  } catch {
+    throw new Error('Invalid endpoint URL format');
+  }
+
+  if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
+    throw new Error('Only HTTP and HTTPS protocols are allowed');
+  }
+
+  const hostname = parsedUrl.hostname.toLowerCase();
+
+  if (BLOCKED_HOSTNAMES.includes(hostname) || isPrivateIP(hostname)) {
+    throw new Error('Access to internal addresses is not allowed');
+  }
+
+  return endpointUrl;
+}
