+import { validateEndpointUrlSync } from '../validateEndpoint';
+
+describe('validateEndpointUrl', () => {
+  it('should accept valid public URLs', () => {
+    expect(() => validateEndpointUrlSync('https://api.openai.com')).not.toThrow();
+    expect(() => validateEndpointUrlSync('https://example.com/v1')).not.toThrow();
+  });
+
+  it('should reject private IP addresses', () => {
+    expect(() => validateEndpointUrlSync('http://127.0.0.1/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://10.0.0.1/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://172.16.0.1/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://192.168.1.1/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://169.254.1.1/v1')).toThrow();
+  });
+
+  it('should reject localhost', () => {
+    expect(() => validateEndpointUrlSync('http://localhost/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://localhost.localdomain/v1')).toThrow();
+  });
+
+  it('should reject invalid protocols', () => {
+    expect(() => validateEndpointUrlSync('ftp://example.com')).toThrow();
+    expect(() => validateEndpointUrlSync('file:///etc/passwd')).toThrow();
+  });
+
+  it('should reject invalid URLs', () => {
+    expect(() => validateEndpointUrlSync('not-a-url')).toThrow();
+    expect(() => validateEndpointUrlSync('')).toThrow();
+  });
+
+  it('should reject IPv6 loopback', () => {
+    expect(() => validateEndpointUrlSync('http://[::1]/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://[::]/v1')).toThrow();
+  });
+
+  it('should reject IPv6 private ranges', () => {
+    expect(() => validateEndpointUrlSync('http://[fc00::1]/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://[fd00::1]/v1')).toThrow();
+    expect(() => validateEndpointUrlSync('http://[fe80::1]/v1')).toThrow();
+  });
+
+  it('should reject DNS rebinding attempts', () => {
+    // These domains resolve to internal IPs
+    // Note: Actual DNS resolution check is in async version
