+
+  it('should accept http protocol', () => {
+    expect(() => validateEndpointUrlSync('http://api.example.com/v1')).not.toThrow();
+  });
+
+  it('should handle URLs with ports', () => {
+    expect(() => validateEndpointUrlSync('https://api.example.com:8080/v1')).not.toThrow();
