+package org.apache.streampipes.commons.utils;
+
+import org.apache.streampipes.commons.exceptions.UrlValidationException;
+
+import java.net.InetAddress;
+import java.net.MalformedURLException;
+import java.net.URL;
+import java.net.UnknownHostException;
+import java.util.Set;
+
+/**
+ * Utility class for validating URLs to prevent SSRF attacks.
+ */
+public class UrlValidator {
+
+    private static final Set<String> ALLOWED_SCHEMES = Set.of("http", "https");
+
+    private UrlValidator() {
+        // Utility class - no instantiation
+    }
+
+    /**
+     * Validates a URL string to ensure it is safe for server-side requests.
+     * Prevents SSRF by blocking internal/private IP addresses and non-HTTP schemes.
+     *
+     * @param urlString the URL string to validate
+     * @throws UrlValidationException if the URL is invalid or points to a forbidden address
+     */
+    public static void validate(String urlString) throws UrlValidationException {
+        if (urlString == null || urlString.isBlank()) {
+            throw new UrlValidationException("URL cannot be null or empty");
+        }
+
+        try {
+            URL url = new URL(urlString);
+
+            // Validate scheme - only allow http and https
+            String scheme = url.getProtocol();
+            if (!ALLOWED_SCHEMES.contains(scheme.toLowerCase())) {
+                throw new UrlValidationException("Only HTTP and HTTPS protocols are allowed");
+            }
+
+            // Resolve the host and validate the IP address
+            String host = url.getHost();
+            InetAddress address = InetAddress.getByName(host);
+
+            // Block internal/private IP addresses to prevent SSRF
+            if (address.isLoopbackAddress()) {
+                throw new UrlValidationException("Access to loopback addresses is not allowed");
+            }
+            if (address.isLinkLocalAddress()) {
+                throw new UrlValidationException("Access to link-local addresses is not allowed");
+            }
+            if (address.isSiteLocalAddress()) {
+                throw new UrlValidationException("Access to private network addresses is not allowed");
+            }
+            if (address.isAnyLocalAddress()) {
+                throw new UrlValidationException("Access to wildcard addresses is not allowed");
+            }
+        } catch (MalformedURLException e) {
+            throw new UrlValidationException("Invalid URL format: " + e.getMessage(), e);
+        } catch (UnknownHostException e) {
+            throw new UrlValidationException("Unable to resolve host: " + e.getMessage(), e);
+        }
+    }
+}
